"""Writes docs/discrete/COVERAGE.md and COVERAGE.csv from the built banks, partner checks, cheat sheets and tools.
Usage (repository root): python3 tools/discrete-math/report.py"""
import json, os, re, subprocess, collections, csv
ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
skills = json.loads(subprocess.check_output(['node', '-e', "global.window=global;require('./course-catalog.js');require('./data.js');const c=LIBRARY.courses.find(c=>c.id==='discrete');console.log(JSON.stringify(c.units.map(u=>({id:u.id,name:u.name,skills:MK_COURSE_CATALOG.getSkillRecords('discrete',u.id)}))))"], cwd=ROOT))
pairs = json.load(open(os.path.join(ROOT, 'tools/discrete-math/partner/pairs.json')))
tools = {t['unit']: t['title'] for t in json.load(open(os.path.join(ROOT, 'tools/interactive-math-discrete/manifest.json')))['tools']}
tools['linear-programming'] = 'Feasible Region Optimizer (reused from Algebra 2)'
F = {'short-answer': 'SA', 'multiple-choice': 'MC', 'select-all': 'SEL', 'open-response': 'OR'}
md = ['# Discrete Math coverage report', '', 'Generated by `tools/discrete-math/report.py` from the built files. Levels: CP2 / CP1 / Honors. Formats: SA short answer, MC multiple choice (misconception distractors), SEL select all, OR open response (≥ 4 parts). EA = error-analysis items.', '']
rows = []; T = collections.Counter()
md += ['## Summary by unit', '', '| # | Unit | Questions | CP2 / CP1 / Honors | SA / MC / SEL / OR | Diagrams | EA (CP2/CP1/H) | Partner pairs (2 sets × 3 levels) | Cheat sheet | Interactive tool |', '|---|---|---|---|---|---|---|---|---|---|']
detail = []
for i, u in enumerate(skills, 1):
    qs = json.load(open(os.path.join(ROOT, 'question-banks/discrete', u['id'] + '.json')))['questions']
    lv = collections.Counter(q['level'] for q in qs); fm = collections.Counter(q['format'] for q in qs)
    dg = sum(1 for q in qs if q.get('diagram')); ea = collections.Counter(q['level'] for q in qs if re.search(r'family: [^)]*_error\)', q.get('sourceNotes', '')))
    pp = {k: len(v) for k, v in pairs.items() if k.startswith(u['id'] + '|')}
    cs = os.path.exists(os.path.join(ROOT, 'artifacts/discrete-%s-cheat-sheet/worksheet.pdf' % u['id']))
    md.append('| %d | %s | %d | %d / %d / %d | %d / %d / %d / %d | %d | %d / %d / %d | %s | %s | %s |' % (i, u['name'], len(qs), lv['cp2'], lv['cp1'], lv['honors'], fm['short-answer'], fm['multiple-choice'], fm['select-all'], fm['open-response'], dg, ea['cp2'], ea['cp1'], ea['honors'],
        ' · '.join('%s %s: %d' % (k.split('|')[2].upper().replace('HONORS', 'H'), 'set ' + k.split('|')[1], v) for k, v in sorted(pp.items())), 'yes (2 pages)' if cs else 'MISSING', tools.get(u['id'], '— (none; see exceptions)')))
    T.update(lv); T['q'] += len(qs); T['dg'] += dg; T['ea'] += sum(ea.values()); T['pairs'] += sum(pp.values())
    detail += ['', '### Unit %d: %s (`%s`)' % (i, u['name'], u['id']), '', '| Skill ID | Skill | CP2 | CP1 | Honors | Total | SA | MC | SEL | OR | Diagrams |', '|---|---|---|---|---|---|---|---|---|---|---|']
    for s in u['skills']:
        sq = [q for q in qs if q['skillId'] == s['id']]; l = collections.Counter(q['level'] for q in sq); f = collections.Counter(q['format'] for q in sq)
        detail.append('| `%s` | %s | %d | %d | %d | %d | %d | %d | %d | %d | %d |' % (s['id'], s['name'], l['cp2'], l['cp1'], l['honors'], len(sq), f['short-answer'], f['multiple-choice'], f['select-all'], f['open-response'], sum(1 for q in sq if q.get('diagram'))))
        rows.append([u['id'], s['id'], s['name'], l['cp2'], l['cp1'], l['honors'], len(sq), f['short-answer'], f['multiple-choice'], f['select-all'], f['open-response'], sum(1 for q in sq if q.get('diagram'))])
md += ['', '**Totals:** %d questions (CP2 %d, CP1 %d, Honors %d), %d with diagrams, %d error-analysis items, %d matched partner pairs, 10 cheat sheets, 9 Interactive Math tools (8 new + 1 reused).' % (T['q'], T['cp2'], T['cp1'], T['honors'], T['dg'], T['ea'], T['pairs']), '',
       'Every skill in `course-catalog.js` has at least 30 questions and at least 8 per level (checked by `scripts/test-discrete-bank.cjs`).', '', '## Coverage by skill'] + detail
open(os.path.join(ROOT, 'docs/discrete/COVERAGE.md'), 'w').write('\n'.join(md) + '\n')
with open(os.path.join(ROOT, 'docs/discrete/COVERAGE.csv'), 'w', newline='') as f:
    w = csv.writer(f); w.writerow(['unit', 'skill_id', 'skill', 'cp2', 'cp1', 'honors', 'total', 'short_answer', 'multiple_choice', 'select_all', 'open_response', 'diagrams']); w.writerows(rows)
print('wrote docs/discrete/COVERAGE.md and COVERAGE.csv:', T['q'], 'questions,', len(rows), 'skills')
